require_once __DIR__.'/../includes/bootstrap.php';if($_SERVER['REQUEST_METHOD']!=='POST'){http_response_code(405);header('Allow: POST');exit('Metode tidak diizinkan.');}verify_csrf();$workspace=require_permission('edit_data');$id=filter_var($_POST['dataset_id']??null,FILTER_VALIDATE_INT);$st=$GLOBALS['pdo']->prepare('SELECT d.source_id,s.storage_path FROM datasets d JOIN data_sources s ON s.id=d.source_id WHERE d.id=? AND d.workspace_id=? LIMIT 1');$st->execute([$id,$workspace['id']]);$row=$st->fetch();if(!$row){flash('error','Dataset tidak ditemukan.');redirect('datasets/index.php');}$GLOBALS['pdo']->beginTransaction();try{$GLOBALS['pdo']->prepare('DELETE FROM datasets WHERE id=? AND workspace_id=?')->execute([$id,$workspace['id']]);$st=$GLOBALS['pdo']->prepare('SELECT COUNT(*) FROM datasets WHERE source_id=?');$st->execute([$row['source_id']]);if((int)$st->fetchColumn()===0)$GLOBALS['pdo']->prepare('DELETE FROM data_sources WHERE id=?')->execute([$row['source_id']]);$GLOBALS['pdo']->commit();$path=(string)($row['storage_path']??'');if($path&&str_starts_with($path,APP_ROOT.'/storage/private/')&&is_file($path))@unlink($path);audit_log('dataset.deleted','dataset',(int)$id);flash('success','Dataset dan file privat terkait dihapus.');}catch(Throwable $e){if($GLOBALS['pdo']->inTransaction())$GLOBALS['pdo']->rollBack();flash('error','Dataset belum dapat dihapus.');error_log('Datanix dataset deletion failed: '.$e->getMessage());}redirect('datasets/index.php');
